examples.code:
#include <cassert>
#include <iterator>

int main() {
    int a[]{9, 8, 7, 6};
    //            │  └───── x, y
    //            └──────── z

    // “x” and “y” are equal, but “x” is greater than “z”
    std::move_iterator<int *> x{std::end(a) - 1}, y{std::end(a) - 1},
        z{std::end(a) - 2};

    // two-way comparisons
    assert(x == y);
    assert(!(x != y));
    assert(!(x < y));
    assert(x <= y);
    assert(!(x == z));
    assert(x != z);
    assert(!(x < z));
    assert(!(x <= z));

    // three-way comparisons
    assert(x <=> y == 0);
    assert(!(x <=> y < 0));
    assert(!(x <=> y > 0));
    assert(!(x <=> z == 0));
    assert(!(x <=> z < 0));
    assert(x <=> z > 0);
}
